(5101, '殷商传奇', '一封来自三千年前的甲骨文情书', 'http://127.0.0.1:9000/msd/covers/ai/5101.jpg', '商王朝的占卜师在甲骨上刻下一段跨越时空的讯息，现代考古学者循着裂纹走进殷商的祭祀与战争。', 2004, 1002, '', 6, 2, 1001, '测试数据：人工审核通过', '2026-10-19 10:00:00.000', '2026-10-20 10:00:00.000', '2026-10-20 10:00:00.000', NULL, 2, '{"scene": "drama_description", "verdict": {"tags": [], "is_violation": false, "violation_reason": ""}, "degraded": false, "auditedAt": "2026-10-20T10:00:00+08:00", "elapsedMs": 0, "degradedFlags": []}', '2026-10-20 10:00:00.000', 128601, 8600, 3200, 410, 0, '2026-10-19 10:00:00.000', '2026-10-26 09:33:32.000'),
(5102, '局中人', '民俗悬疑，借命禁忌', 'http://127.0.0.1:9000/msd/covers/ai/5102.jpg', '一桩山村旧案把几个陌生人困在同一场禁忌仪式里，谁在借命，谁又是真正的局中人。', 2003, 1004, '', 6, 2, 1001, '测试数据：人工审核通过', '2026-10-19 12:00:00.000', '2026-10-20 12:00:00.000', '2026-10-20 12:00:00.000', NULL, 2, '{"scene": "drama_description", "verdict": {"tags": [], "is_violation": false, "violation_reason": ""}, "degraded": false, "auditedAt": "2026-10-20T12:00:00+08:00", "elapsedMs": 0, "degradedFlags": []}', '2026-10-20 12:00:00.000', 96500, 6200, 2100, 280, 0, '2026-10-19 12:00:00.000', '2026-10-26 09:33:32.000'),
(5103, '十日终焉', '十日轮回，逃出终焉之地', 'http://127.0.0.1:9000/msd/covers/ai/5103.jpg', '十个人被关进一座会重置时间的建筑，每过十天一切归零，只有找出规则的人才能离开。', 2003, 1005, '', 6, 2, 1001, '测试数据：人工审核通过', '2026-10-20 10:00:00.000', '2026-10-21 10:00:00.000', '2026-10-21 10:00:00.000', NULL, 2, '{"scene": "drama_description", "verdict": {"tags": [], "is_violation": false, "violation_reason": ""}, "degraded": false, "auditedAt": "2026-10-21T10:00:00+08:00", "elapsedMs": 0, "degradedFlags": []}', '2026-10-21 10:00:00.000', 87300, 5100, 1800, 190, 0, '2026-10-20 10:00:00.000', '2026-10-26 09:33:32.000'),
(5104, '认错相亲对象怎么办', '一场乌龙相亲，撞上对的人', 'http://127.0.0.1:9000/msd/covers/ai/5104.jpg', '替朋友赴约的女生认错了相亲对象，却阴差阳错卷进一段先婚后爱的合约关系。', 2002, 1002, '', 6, 2, 1001, '测试数据：人工审核通过', '2026-10-20 12:00:00.000', '2026-10-21 12:00:00.000', '2026-10-21 12:00:00.000', NULL, 2, '{"scene": "drama_description", "verdict": {"tags": [], "is_violation": false, "violation_reason": ""}, "degraded": false, "auditedAt": "2026-10-21T12:00:00+08:00", "elapsedMs": 0, "degradedFlags": []}', '2026-10-21 12:00:00.000', 156801, 9800, 3900, 520, 0, '2026-10-20 12:00:00.000', '2026-10-26 09:33:32.000'),
(5105, '考研倒计时', '倒计时里的青春与选择', 'http://127.0.0.1:9000/msd/covers/ai/5105.jpg', '备考最后一百天，四个年轻人面对升学、就业和感情的岔路，做出各自的选择。', 2005, 1004, '', 6, 2, 1001, '测试数据：人工审核通过', '2026-10-21 10:00:00.000', '2026-10-22 10:00:00.000', '2026-10-22 10:00:00.000', NULL, 2, '{"scene": "drama_description", "verdict": {"tags": [], "is_violation": false, "violation_reason": ""}, "degraded": false, "auditedAt": "2026-10-22T10:00:00+08:00", "elapsedMs": 0, "degradedFlags": []}', '2026-10-22 10:00:00.000', 74200, 4300, 1500, 160, 0, '2026-10-21 10:00:00.000', '2026-10-26 09:33:32.000'),
(5106, '余波', '丧尸爆发，赶快回家', 'http://127.0.0.1:9000/msd/covers/ai/5106.jpg', '病毒在一夜之间扩散，普通上班族穿越封锁区，只为赶回家确认家人平安。', 2003, 1005, '', 6, 2, 1001, '测试数据：人工审核通过', '2026-10-21 12:00:00.000', '2026-10-22 12:00:00.000', '2026-10-22 12:00:00.000', NULL, 2, '{"scene": "drama_description", "verdict": {"tags": [], "is_violation": false, "violation_reason": ""}, "degraded": false, "auditedAt": "2026-10-22T12:00:00+08:00", "elapsedMs": 0, "degradedFlags": []}', '2026-10-22 12:00:00.000', 68900, 3900, 1300, 140, 0, '2026-10-21 12:00:00.000', '2026-10-26 09:33:32.000'),
(5107, '末日长途', '末日公路，向生而行', 'http://127.0.0.1:9000/msd/covers/ai/5107.jpg', '末日后的第一年，一支临时拼凑的车队沿着废弃高速寻找传说中的安全区。', 2003, 1002, '', 6, 2, 1001, '测试数据：人工审核通过', '2026-10-22 10:00:00.000', '2026-10-23 10:00:00.000', '2026-10-23 10:00:00.000', NULL, 2, '{"scene": "drama_description", "verdict": {"tags": [], "is_violation": false, "violation_reason": ""}, "degraded": false, "auditedAt": "2026-10-23T10:00:00+08:00", "elapsedMs": 0, "degradedFlags": []}', '2026-10-23 10:00:00.000', 52100, 3100, 980, 110, 0, '2026-10-22 10:00:00.000', '2026-10-26 09:33:32.000'),
(5108, '一觉醒来，我来到了一百年后', '百年后的世界，规则全变了', 'http://127.0.0.1:9000/msd/covers/ai/5108.jpg', '男主从病床醒来，发现自己身处一百年后的城市，记忆与现实处处对不上。', 2006, 1004, '', 6, 2, 1001, '测试数据：人工审核通过', '2026-10-22 12:00:00.000', '2026-10-23 12:00:00.000', '2026-10-23 12:00:00.000', NULL, 2, '{"scene": "drama_description", "verdict": {"tags": [], "is_violation": false, "violation_reason": ""}, "degraded": false, "auditedAt": "2026-10-23T12:00:00+08:00", "elapsedMs": 0, "degradedFlags": []}', '2026-10-23 12:00:00.000', 118400, 7600, 2800, 360, 0, '2026-10-22 12:00:00.000', '2026-10-26 09:33:32.000'),
(5109, '全家魔丸', '我上清北', 'http://127.0.0.1:9000/msd/covers/ai/5109.jpg', '一家人为了同一个升学目标闹出一连串乌龙，笑着笑着就把日子过成了团圆。', 2001, 1005, '', 6, 2, 1001, '测试数据：人工审核通过', '2026-10-23 10:00:00.000', '2026-10-24 10:00:00.000', '2026-10-24 10:00:00.000', NULL, 2, '{"scene": "drama_description", "verdict": {"tags": [], "is_violation": false, "violation_reason": ""}, "degraded": false, "auditedAt": "2026-10-24T10:00:00+08:00", "elapsedMs": 0, "degradedFlags": []}', '2026-10-24 10:00:00.000', 91400, 5800, 2200, 250, 0, '2026-10-23 10:00:00.000', '2026-10-26 09:33:32.000')

